const { debounce } = require('./t10_debounce');

// Test function that logs when it's called
let callCount = 0;
const testFn = () => {
  callCount++;
  console.log(`Function called! Total calls: ${callCount}`);
};

// Create debounced version with 100ms delay
const debouncedFn = debounce(testFn, 100);

console.log('Starting debounce test...');

// Simulate a burst of calls
debouncedFn(); // Should not execute immediately
setTimeout(() => debouncedFn(), 50); // Should cancel previous and schedule new
setTimeout(() => debouncedFn(), 100); // Should cancel previous and schedule new
setTimeout(() => debouncedFn(), 150); // Should cancel previous and schedule new
setTimeout(() => debouncedFn(), 200); // Should cancel previous and schedule new

// Wait for all to complete
setTimeout(() => {
  console.log(`Final call count: ${callCount}`);
  if (callCount === 1) {
    console.log('SUCCESS: Only the last call executed after the delay');
  } else {
    console.log('FAILURE: More than one call executed');
  }
}, 300);
```

